#include <DHT.h>
#define DHTPIN 2
#define DHTTYPE DHT11
DHT dht(DHTPIN,DHTTYPE);
LiquidCrystal lcd(12,11,5,4,3,6);
void setup() {
  lcd.begin(16,2);
  dht.begin();
  Serial.begin(9600);
}
void loop() {
  float h=dht.readHumidity();
  float t=dht.readTemperature();
  lcd.setCursor(0,0);
  lcd.print("Temp: ");
  lcd.print(t);
  lcd.print("C");
  lcd.setCursor(0,1);
  lcd.print("Hum: ");
  lcd.print(h);
  lcd.print("%");
  Serial.print(t);
  Serial.print("C ");
  Serial.print(h);
  Serial.println("%");
  delay(2000);
}

