void setup() {
  pinMode(9,OUTPUT);
  Serial.begin(9600);
}
void loop() {
  int raw=analogRead(A0);
  float resistance=10000.0*raw/(1023.0-raw);
  float tempK=1.0/(log(resistance/10000.0)/3950+1.0/298.15);
  float tempC=tempK-273.15;
  int speed=map(tempC,20,40,0,255);
  speed=constrain(speed,0,255);
  analogWrite(9,speed);
  Serial.print(tempC);
  Serial.print("C Fan: ");
  Serial.println(speed);
  delay(500);
}

