  if(level<200) {
    digitalWrite(9,LOW);
    digitalWrite(10,LOW);
    noTone(8);
  } else if(level<500) {
  digitalWrite(9,HIGH);
  digitalWrite(10,LOW);
  noTone(8);
} else {
digitalWrite(9,HIGH);
digitalWrite(10,HIGH);
tone(8,2000);
Serial.println("TANK FULL!");
}
delay(300);
}

