#include <IRremote.h>
int RECV_PIN=11;
IRrecv irrecv(RECV_PIN);
decode_results results;
void setup() {
  Serial.begin(9600);
  irrecv.enableIRIn();
  pinMode(13,OUTPUT);
}
void loop() {
  if(irrecv.decode(&results)) {
    Serial.println(results.value,HEX);
    if(results.value==0xFF00) {
      digitalWrite(13,HIGH);
    } else if(results.value==0xFF01) {
    digitalWrite(13,LOW);
  }
irrecv.resume();
}
}

